import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function serializeErasureRequest(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

/** Repository for the public erasure-request lifecycle. The destructive cleanup
 *  itself lives in the erasure worker. */
export class ErasureRequestRepository {
  async customerExists(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async findActiveRequest(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests
       WHERE merchant_id=$1 AND customer_id=$2 AND status IN ('pending','processing','failed')
       ORDER BY created_at DESC LIMIT 1`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async createRequest(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,status)
       VALUES($1,$2,'pending') RETURNING *`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async enqueueCleanup(
    client: pg.PoolClient,
    erasureRequestId: string,
    merchantId: string,
  ): Promise<void> {
    const active = await client.query(
      `SELECT 1 FROM operations.jobs
       WHERE queue='erasure' AND status IN ('pending','processing','retry')
         AND payload->>'erasureRequestId'=$1 LIMIT 1`,
      [erasureRequestId],
    );
    if (active.rowCount) return;
    await client.query(
      `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
       VALUES('erasure','erasure_request',$1,$2)`,
      [merchantId, { erasureRequestId }],
    );
  }

  async markReposted(client: pg.PoolClient, erasureRequestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='pending', last_error=NULL, updated_at=now()
       WHERE id=$1 AND status='failed'`,
      [erasureRequestId],
    );
  }

  async findResponse(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findResponseById(id: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE id=$1`,
      [id],
    );
    return result.rows[0];
  }
}","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts"}

{"command":"create","file_text":"import { v4 as uuid } from 'uuid';
import { transaction } from '../../../packages/database/src/pool.js';
import {
  ErasureRequestRepository,
  serializeErasureRequest,
  type ErasureRequestResponse,
} from './erasure-repository.js';
import { completeIdempotency, requestHash, reserveIdempotency } from './idempotency.js';

export class ErasureService {
  constructor(private readonly repository = new ErasureRequestRepository()) {}

  /**
   * Creates or resumes a customer data deletion request.
   *
   * - 404 when the customer does not exist or belongs to another merchant,
   *   without reserving the idempotency key or mutating data.
   * - Reusing an idempotency key for the same customer returns the saved
   *   request; reusing it for a different customer returns 409.
   * - A new key for a customer that already has a request returns that existing
   *   request instead of starting another workflow. A failed request is
   *   re-queued for another cleanup attempt.
   */
  async create(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestResponse> {
    if (!await this.repository.customerExists(merchantId, customerId)) {
      throw Object.assign(new Error('customer not found'), { statusCode: 404 });
    }
    const hash = requestHash({ customerId });

    return await transaction(async (client) => {
      const replay = await reserveIdempotency(client, merchantId, 'erasure-request', idempotencyKey, hash);
      if (replay) return replay.body as ErasureRequestResponse;

      const existing = await this.repository.findActiveRequest(client, merchantId, customerId);
      let row = existing;
      if (existing) {
        if (existing.status === 'failed') {
          await this.repository.markReposted(client, existing.id);
          row = { ...existing, status: 'pending', last_error: null, updated_at: new Date() };
        }
      } else {
        row = await this.repository.createRequest(client, merchantId, customerId);
      }
      await this.repository.enqueueCleanup(client, row.id, merchantId);
      await this.audit(client, merchantId, customerId, row.id);
      const response = serializeErasureRequest(row);
      await completeIdempotency(client, merchantId, 'erasure-request', idempotencyKey, 202, response);
      return response;
    });
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestResponse> {
    const row = await this.repository.findResponse(merchantId, requestId);
    if (!row) throw Object.assign(new Error('erasure request not found'), { statusCode: 404 });
    return serializeErasureRequest(row);
  }

  private async audit(
    client: import('pg').PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
       VALUES($1,'api_key','customer',$2,'erasure.requested',$3,$4)`,
      [merchantId, customerId, { requestId }, uuid()],
    );
  }
}","path":"/workspace/source/apps/customer-service/src/erasure-service.ts"}

