{"command":"create","file_text":"import type pg from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface CustomerProfile {
  id: string;
  merchant_id: string;
  email: string;
}

/**
 * The set of jsonb keys that may carry personal data inside event/document
 * payloads. Removing them keeps the financial meaning of a record while
 * stripping identity.
 */
const PII_JSONB_KEYS = [
  'email', 'name', 'phone', 'customerEmail', 'body', 'subject', 'metadata',
  'externalReference', 'customer', 'contact', 'address', 'billingName',
  'last4', 'billingAddress',
];

/** Performs the idempotent customer data deletion. Every step is safe to retry:
 *  deletes remove whatever remains, scrubs overwrite fields that are already
 *  scrubbed. Financial records keep their amounts and currency; only identity
 *  is stripped. */
export class ErasureCleanupRepository {
  async loadProfile(merchantId: string, customerId: string): Promise<CustomerProfile | undefined> {
    const result = await pool.query<CustomerProfile>(
      `SELECT id, merchant_id, email FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findObjectKeysForCustomer(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  /** Cancels receipt jobs and scrubs event payloads that have not been published
   *  yet, so delayed work cannot recreate personal data. */
  async suppressDelayedWork(merchantId: string, customerId: string): Promise<void> {
    await transaction(async (client) => {
      await client.query(
        `UPDATE operations.jobs
         SET status='cancelled', locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, last_error='customer_erased'
         WHERE queue='documents' AND status IN ('pending','retry','processing')
           AND payload->>'customerId'=$1`,
        [customerId],
      );
      const scrubbed = PII_JSONB_KEYS.map((key) => `'${key}'`).join(',');
      await client.query(
        `UPDATE operations.outbox_events
         SET payload = payload - ARRAY[${scrubbed}]::text[]
         WHERE merchant_id=$1
           AND (aggregate_id=$2 OR payload->>'customerId'=$2)
           AND status IN ('pending','publishing')`,
        [merchantId, customerId],
      );
    });
  }

  /** Removes notification records and queued emails for the customer. */
  async removeNotifications(merchantId: string, customerId: string): Promise<void> {
    await transaction(async (client) => {
      await client.query(
        `UPDATE operations.email_deliveries
         SET status='cancelled', cancelled_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
         WHERE merchant_id=$1 AND customer_id=$2 AND status IN ('pending','failed','processing')`,
        [merchantId, customerId],
      );
      await client.query(
        `DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      await client.query(
        `DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      await client.query(
        `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
    });
  }

  /** Scrubs identity from retained financial records and deletes customer-owned
   *  personal data tables, then removes the customer row. */
  async scrubFinancialAndDeleteCustomer(merchantId: string, customerId: string): Promise<void> {
    const pii = PII_JSONB_KEYS.map((key) => `'${key}'`).join(',');
    await transaction(async (client) => {
      await this.scrubFinancialRecords(client, merchantId, customerId, pii);
      await this.deleteCustomerOwnedData(client, customerId);
      await client.query(
        `DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
    });
  }

  private async scrubFinancialRecords(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    pii: string,
  ): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot = customer_snapshot - ARRAY[${pii}]::text[],
           description = NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot = billing_snapshot - ARRAY[${pii}]::text[],
           object_key = NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.refunds
       SET customer_email = NULL
       WHERE payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.payment_attempts
       SET request_payload = request_payload - ARRAY[${pii}]::text[]
       WHERE merchant_id=$1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email='redacted', name='redacted', external_reference='redacted', updated_at=now()
       WHERE payflow_customer_id=$1`,
      [customerId],
    );
    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL, customer_id=NULL, properties = properties - ARRAY[${pii}]::text[]
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.dead_letters
       SET payload = payload - ARRAY[${pii}]::text[]
       WHERE payload->>'customerId'=$1`,
      [customerId],
    );
  }

  private async deleteCustomerOwnedData(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.addresses WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.support_participants WHERE customer_id=$1`, [customerId]);
    await client.query(
      `DELETE FROM customers.support_messages WHERE author_type='customer' AND author_id=$1`,
      [customerId],
    );
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE customer_id=$1`, [customerId]);
  }

  /** Deletes document manifests for the customer. MinIO objects are removed
   *  separately by the worker. */
  async deleteDocumentManifests(merchantId: string, customerId: string): Promise<void> {
    await pool.query(
      `DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async markProcessing(id: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, last_error=NULL, updated_at=now()
       WHERE id=$1 AND status IN ('pending','failed')`,
      [id],
    );
  }

  async markCompleted(id: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), last_error=NULL, updated_at=now()
       WHERE id=$1`,
      [id],
    );
  }

  async markFailed(id: string, code: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2, updated_at=now()
       WHERE id=$1 AND status='processing'`,
      [id, code],
    );
  }
}","path":"/workspace/source/apps/erasure-worker/src/repository.ts"}

{"command":"create","file_text":"import { randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import {
  claimJob,
  completeJob,
  failJob,
  recoverExpiredJobLeases,
  type ClaimedJob,
} from '../../../packages/operations/src/job-lifecycle.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { ErasureCleanupRepository } from './repository.js';

process.env.SERVICE_NAME = 'erasure-worker';

interface ErasureJobPayload {
  erasureRequestId: string;
}

const repository = new ErasureCleanupRepository();
const redis = new Redis(config().REDIS_URL);
const workerId = `erasure-worker-${randomUUID()}`;

class ErasureStepError extends Error {
  constructor(readonly code: string, cause: unknown) {
    super(code, { cause });
  }
}

async function withCode<T>(code: string, operation: () => Promise<T>): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    throw new ErasureStepError(code, error);
  }
}

async function deleteObjectStoreObjects(objectKeys: string[]): Promise<void> {
  for (const objectKey of objectKeys) {
    try {
      await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
    } catch (error) {
      // MinIO reports "NoSuchKey" when an object is already gone; treat that as success.
      const message = error instanceof Error ? error.message : String(error);
      if (!/NoSuchKey|Not Found|does not exist/i.test(message)) throw error;
    }
  }
}

async function deleteSearchDocument(merchantId: string, customerId: string): Promise<void> {
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (!/not_found|404/i.test(message)) throw error;
  }
