test('erasure request responses are serialized with stable camelCase fields', () => {
  const now = new Date('2026-08-20T12:00:00.000Z');
  const completed = new Date('2026-08-20T12:05:00.000Z');
  assert.deepEqual(
    serializeErasureRequest({
      id: '0ad18e87-1c3f-4af0-aace-345ab19f7a4a',
      merchant_id: '10000000-0000-4000-8000-000000000001',
      customer_id: '147790aa-64d8-4f18-a650-1b3b006ed06e',
      status: 'completed',
      attempts: 1,
      last_error: null,
      created_at: now,
      updated_at: completed,
      completed_at: completed,
    }),
    {
      id: '0ad18e87-1c3f-4af0-aace-345ab19f7a4a',
      customerId: '147790aa-64d8-4f18-a650-1b3b006ed06e',
      status: 'completed',
      attempts: 1,
      createdAt: '2026-08-20T12:00:00.000Z',
      updatedAt: '2026-08-20T12:05:00.000Z',
      completedAt: '2026-08-20T12:05:00.000Z',
      lastError: null,
    },
  );
});

test('a pending erasure request reports null completion and error fields', () => {
  const now = new Date('2026-08-20T12:00:00.000Z');
  const response = serializeErasureRequest({
    id: '1c3f-0000-0000-0000-000000000001',
    merchant_id: '10000000-0000-4000-8000-000000000001',
    customer_id: '2c3f-0000-0000-0000-000000000002',
    status: 'pending',
    attempts: 0,
    last_error: null,
    created_at: now,
    updated_at: now,
    completed_at: null,
  });
  assert.equal(response.status, 'pending');
  assert.equal(response.completedAt, null);
  assert.equal(response.lastError, null);
  assert.equal(response.attempts, 0);
});

test('erasure idempotency hashes are keyed by the customer identifier only', () => {
  const customerId = '147790aa-64d8-4f18-a650-1b3b006ed06e';
  assert.equal(requestHash({ customerId }), requestHash({ customerId }));
  assert.notEqual(requestHash({ customerId }), requestHash({ customerId: '147790aa-64d8-4f18-a650-1b3b006ed06f' }));
});","path":"/workspace/source/tests/erasure.test.ts"}

